//! Route names and parameters generated by bulk and singleton resources.

use crate::common::{
    LARAVEL_SRC_COMPOSER, complete_labels_at_opened, create_initialized_psr4_workspace,
    definition_locations, goto_definition_at, hover_text_at, messages_with_code, position_after,
    position_of,
};
use phpantom_lsp::Backend;
use tower_lsp::lsp_types::Url;

async fn workspace(routes: &str, body: &str) -> (Backend, tempfile::TempDir, Url, String) {
    let consumer = format!(
        "<?php\nnamespace App;\nclass Links {{\n    public function show(): void {{\n{body}\n    }}\n}}\n"
    );
    let (backend, dir, uri) = create_initialized_psr4_workspace(
        LARAVEL_SRC_COMPOSER,
        &[("routes/web.php", routes), ("src/Links.php", &consumer)],
        "src/Links.php",
    )
    .await;
    (backend, dir, uri, consumer)
}

/// Completion and the unknown-route diagnostic must agree on generated names.
async fn assert_names(routes: &str, known: &[&str], unknown: &[&str]) {
    let mut body = String::from("        route('');\n");
    for name in known.iter().chain(unknown) {
        body.push_str(&format!("        route('{name}');\n"));
    }
    let (backend, _dir, uri, consumer) = workspace(routes, &body).await;
    let position = position_after(&consumer, "route('");
    let labels = complete_labels_at_opened(&backend, &uri, position.line, position.character).await;
    let mut diagnostics = Vec::new();
    backend.collect_slow_diagnostics(uri.as_str(), &consumer, &mut diagnostics);
    let messages = messages_with_code(&diagnostics, "invalid_laravel_route");
    for name in known {
        assert!(
            labels.iter().any(|label| label == name),
            "missing {name}: {labels:?}"
        );
        assert!(
            !messages
                .iter()
                .any(|message| message.contains(&format!("'{name}'"))),
            "registered route {name} was flagged: {messages:?}"
        );
    }
    for name in unknown {
        assert!(
            !labels.iter().any(|label| label == name),
            "unexpected {name}: {labels:?}"
        );
        assert!(
            messages
                .iter()
                .any(|message| message.contains(&format!("'{name}'"))),
            "unknown route {name} was not flagged: {messages:?}"
        );
    }
}

async fn assert_parameters(routes: &str, expected: &[(&str, &[&str])]) {
    let body: String = expected
        .iter()
        .map(|(name, _)| format!("        route('{name}', ['']);\n"))
        .collect();
    let (backend, _dir, uri, consumer) = workspace(routes, &body).await;
    for (name, parameters) in expected {
        let position = position_after(&consumer, &format!("route('{name}', ['"));
        let labels =
            complete_labels_at_opened(&backend, &uri, position.line, position.character).await;
        assert_eq!(labels.as_slice(), *parameters, "parameters of {name}");
    }
}

#[tokio::test]
async fn plural_resources_generate_every_entry_and_api_resources_omit_forms() {
    assert_names(
        r#"<?php
Route::resources(['photos' => PhotoController::class, 'videos' => VideoController::class]);
Route::apiResources(['posts' => PostController::class, 'comments' => CommentController::class]);
"#,
        &[
            "photos.index",
            "photos.create",
            "photos.store",
            "photos.show",
            "photos.edit",
            "photos.update",
            "photos.destroy",
            "videos.index",
            "videos.create",
            "videos.store",
            "videos.show",
            "videos.edit",
            "videos.update",
            "videos.destroy",
            "posts.index",
            "posts.store",
            "posts.show",
            "posts.update",
            "posts.destroy",
            "comments.index",
            "comments.store",
            "comments.show",
            "comments.update",
            "comments.destroy",
        ],
        &[
            "posts.create",
            "posts.edit",
            "comments.create",
            "comments.edit",
            "photos.list",
        ],
    )
    .await;
}

const GROUPED_RESOURCES: &str = r#"<?php
Route::prefix('teams/{team}')->name('admin.')->group(function () {
    Route::resources([
        'photos.comments' => CommentController::class,
        'users.posts' => PostController::class,
    ], [
        'only' => ['index', 'show', 'update'],
        'except' => ['update'],
        'parameters' => ['photos' => 'photo_slug', 'comments' => 'comment_slug', 'users' => 'owner', 'posts' => 'post_slug'],
        'shallow' => true,
    ]);
});
"#;

#[tokio::test]
async fn bulk_resource_options_apply_to_each_entry_under_its_group() {
    assert_names(
        GROUPED_RESOURCES,
        &[
            "admin.photos.comments.index",
            "admin.comments.show",
            "admin.users.posts.index",
            "admin.posts.show",
        ],
        &[
            "admin.photos.comments.show",
            "admin.users.posts.show",
            "admin.comments.update",
            "admin.posts.update",
            "admin.comments.create",
        ],
    )
    .await;
    assert_parameters(
        GROUPED_RESOURCES,
        &[
            ("admin.photos.comments.index", &["team", "photo_slug"]),
            ("admin.comments.show", &["team", "comment_slug"]),
            ("admin.users.posts.index", &["team", "owner"]),
            ("admin.posts.show", &["team", "post_slug"]),
        ],
    )
    .await;
}

#[tokio::test]
async fn bulk_resources_accept_named_arguments_and_route_name_overrides() {
    assert_names(
        r#"<?php
Route::name('admin.')->group(function () {
    Route::resources(options: ['only' => ['index', 'show'], 'as' => 'media', 'names' => ['show' => 'photos.preview']], resources: ['photos' => PhotoController::class]);
    Route::apiResources(options: ['only' => ['create', 'edit'], 'except' => ['edit'], 'names' => 'library'], resources: ['books' => BookController::class]);
});
"#,
        &["admin.media.photos.index", "admin.photos.preview", "admin.library.create"],
        &["admin.media.photos.show", "admin.photos.show", "admin.library.edit", "admin.library.index", "admin.books.create"],
    )
    .await;
}

#[tokio::test]
async fn plural_calls_use_router_receivers_and_ignore_lookalike_builders() {
    assert_names(
        r#"<?php
use Illuminate\Support\Facades\Route;
Route::resources(['photos' => PhotoController::class], ['only' => ['show']]);
\Illuminate\Support\Facades\Route::apiResources(['posts' => PostController::class], ['only' => ['show']]);
Route::group(['as' => 'admin.'], function ($r) {
    $r->singletons(['profile' => ProfileController::class]);
});
$builder->resources(['unrelated' => OtherController::class]);
OtherRouter::apiSingleton('unrelated', OtherController::class);
"#,
        &["photos.show", "posts.show", "admin.profile.show", "admin.profile.edit", "admin.profile.update"],
        &["unrelated.index", "unrelated.show", "photos.index", "posts.edit"],
    )
    .await;
}

#[tokio::test]
async fn singleton_and_plural_singletons_have_no_member_id_or_index() {
    let routes = r#"<?php
Route::singleton('profile', ProfileController::class);
Route::apiSingleton('settings', SettingsController::class);
Route::singletons(['avatar' => AvatarController::class, 'cover' => CoverController::class]);
Route::apiSingletons(['preferences' => PreferencesController::class, 'status' => StatusController::class]);
"#;
    assert_names(
        routes,
        &[
            "profile.show",
            "profile.edit",
            "profile.update",
            "settings.show",
            "settings.update",
            "avatar.show",
            "avatar.edit",
            "avatar.update",
            "cover.show",
            "cover.edit",
            "cover.update",
            "preferences.show",
            "preferences.update",
            "status.show",
            "status.update",
        ],
        &[
            "profile.index",
            "profile.create",
            "profile.store",
            "profile.destroy",
            "settings.edit",
            "settings.store",
            "avatar.index",
            "preferences.edit",
        ],
    )
    .await;
    assert_parameters(
        routes,
        &[
            ("profile.show", &[]),
            ("profile.edit", &[]),
            ("settings.update", &[]),
            ("avatar.show", &[]),
        ],
    )
    .await;
}

