#[tokio::test]
async fn singleton_options_and_named_arguments_override_api_defaults() {
    assert_names(
        r#"<?php
Route::singletons(options: ['creatable' => true, 'only' => ['show', 'store', 'destroy'], 'except' => ['destroy']], singletons: ['profile' => ProfileController::class, 'avatar' => AvatarController::class]);
Route::apiSingletons(singletons: ['settings' => SettingsController::class], options: ['destroyable' => true]);
Route::apiSingleton(options: ['only' => ['edit']], controller: StatusController::class, name: 'status');
Route::singleton(options: ['creatable' => true], name: 'cover', controller: CoverController::class)->only('create', 'store')->except('store');
"#,
        &["profile.show", "profile.store", "avatar.show", "avatar.store", "settings.show", "settings.update", "settings.destroy", "status.edit", "cover.create"],
        &["profile.edit", "profile.destroy", "avatar.destroy", "settings.edit", "settings.store", "status.show", "cover.store", "cover.destroy"],
    )
    .await;
}

#[tokio::test]
async fn nested_singleton_names_and_parameters_obey_fluent_modifiers() {
    let routes = r#"<?php
Route::prefix('teams/{team}')->name('admin.')->group(function () {
    Route::singleton('albums.cover', CoverController::class)
        ->creatable()->only(['show', 'edit', 'store', 'destroy'])->except(['store'])
        ->names(['show' => 'albums.preview'])->name('edit', 'cover.form')
        ->parameters(['albums' => 'album_slug']);
});
"#;
    assert_names(
        routes,
        &[
            "admin.albums.preview",
            "admin.cover.form",
            "admin.albums.cover.destroy",
        ],
        &[
            "admin.albums.cover.show",
            "admin.albums.cover.edit",
            "admin.albums.cover.store",
            "admin.albums.cover.create",
        ],
    )
    .await;
    assert_parameters(
        routes,
        &[
            ("admin.albums.preview", &["team", "album_slug"]),
            ("admin.cover.form", &["team", "album_slug"]),
            ("admin.albums.cover.destroy", &["team", "album_slug"]),
        ],
    )
    .await;
}

#[tokio::test]
async fn singleton_shallow_keeps_show_and_creation_nested() {
    let routes = r#"<?php
Route::singleton('photos.profile', ProfileController::class, ['shallow' => true])->creatable();
"#;
    assert_names(
        routes,
        &[
            "photos.profile.show",
            "photos.profile.create",
            "photos.profile.store",
            "profile.edit",
            "profile.update",
            "profile.destroy",
        ],
        &[
            "profile.show",
            "profile.create",
            "profile.store",
            "photos.profile.edit",
            "photos.profile.update",
            "photos.profile.destroy",
        ],
    )
    .await;
    assert_parameters(
        routes,
        &[
            ("photos.profile.show", &["photo"]),
            ("photos.profile.create", &["photo"]),
            ("photos.profile.store", &["photo"]),
            ("profile.edit", &[]),
            ("profile.update", &[]),
            ("profile.destroy", &[]),
        ],
    )
    .await;
}

#[tokio::test]
async fn trailing_slashes_and_empty_resource_names_generate_bare_action_names() {
    for resource in ["/photos/", "photos/", ""] {
        let routes = format!(
            "<?php\nRoute::resource('{resource}', PhotoController::class)->only(['index', 'show']);\n"
        );
        assert_names(
            &routes,
            &["index", "show"],
            &["photos.index", "photos.show", "create"],
        )
        .await;
    }
    assert_names(
        "<?php\nRoute::resources(['/photos/' => PhotoController::class], ['only' => ['show']]);\n",
        &["show"],
        &["photos.show", "photos.index"],
    )
    .await;
}

#[tokio::test]
async fn leading_slashes_and_doubled_dots_preserve_laravels_generated_names() {
    assert_names(
        r#"<?php
Route::resource('/photos', PhotoController::class)->only('show');
Route::apiResources(['photos..comments' => CommentController::class]);
"#,
        &[
            "photos.show",
            "photos..comments.index",
            "photos..comments.show",
            "photos..comments.store",
            "photos..comments.update",
            "photos..comments.destroy",
        ],
        &[
            "show",
            "/photos.show",
            "photos.comments.index",
            "photos.comments.show",
            "photos..comments.edit",
        ],
    )
    .await;
}

#[tokio::test]
async fn singleton_resource_names_keep_empty_final_segments() {
    for resource in ["/profile/", "profile/", ""] {
        let routes = format!("<?php\nRoute::singleton('{resource}', ProfileController::class);\n");
        assert_names(
            &routes,
            &["show", "edit", "update"],
            &["profile.show", "profile.edit", "index"],
        )
        .await;
    }
    assert_names(
        "<?php\nRoute::apiSingleton('photos..profile', ProfileController::class);\n",
        &["photos..profile.show", "photos..profile.update"],
        &["photos.profile.show", "photos..profile.edit"],
    )
    .await;
}

#[tokio::test]
async fn generated_route_definitions_land_on_the_individual_registration_literals() {
    let routes = r#"<?php
Route::resources([
    'photos' => PhotoController::class,
    /* 📷 */ 'videos' => VideoController::class,
]);
Route::singleton('profile', ProfileController::class);
"#;
    let (backend, dir, uri, consumer) = workspace(
        routes,
        "        route('photos.show');\n        route('videos.update');\n        route('profile.edit');",
    )
    .await;
    let routes_uri = Url::from_file_path(dir.path().join("routes/web.php")).unwrap();
    for (name, literal) in [
        ("photos.show", "'photos'"),
        ("videos.update", "'videos'"),
        ("profile.edit", "'profile'"),
    ] {
        let mut position = position_after(&consumer, &format!("route('{name}"));
        position.character -= 1;
        let locations = definition_locations(
            goto_definition_at(&backend, &uri, position.line, position.character).await,
        );
        assert_eq!(locations.len(), 1, "{name}: {locations:?}");
        assert_eq!(locations[0].uri, routes_uri);
        let mut expected = position_of(routes, literal);
        expected.character += 1;
        assert_eq!(locations[0].range.start, expected, "{name}");
        let hover = hover_text_at(&backend, &uri, position.line, position.character)
            .await
            .expect("a generated route should hover");
        assert!(hover.contains("routes/web.php"), "{name}: {hover}");
    }
}
